template:
fn extract⟦g⟧(
    _p: &str,
    target: ⟦t⟧,
) -> &'a str {
    &target[..3]
}

fn main() {
    let p = String::from("key");
    let t = String::from("12345");
    let res = extract(&p, &t);
    println!("{res}");
}

tests:
#[test]
fn extracts_prefix() {
    let p = String::from("key");
    let t = String::from("12345");
    assert_eq!(extract(&p, &t), "123");
}
